				      struct worker_pool *caller_pool)
{
	struct pool_workqueue *pwq;
	struct work_struct *work;

	raw_spin_lock(&nna->lock);
	pwq = list_first_entry_or_null(&nna->pending_pwqs,
				       struct pool_workqueue, pending_node);
